def policy(env, agent_id) -> int:
    """Return an action (int 0-8) for the given agent."""
    if int(env.agent_timeout[agent_id]) > 0:
        return 7  # STAND while removed

    ar = int(env.agent_pos[agent_id][0])
    ac = int(env.agent_pos[agent_id][1])
    orient = int(env.agent_orient[agent_id])

    # Static division of labor: 1/3 of agents clean, the rest harvest
    num_cleaners = max(1, int(env.n_agents) // 3)
    is_cleaner = (agent_id < num_cleaners)

    if is_cleaner:
        # Helper to simulate beam hits for an orientation
        def get_hits(o):
            hits = 0
            if o == 0:   # North
                for r in range(ar - 5, ar):
                    for c in range(ac - 1, ac + 2):
                        if 0 <= r < env.height and 0 <= c < env.width and env.waste[r, c]:
                            hits += 1
            elif o == 1: # East
                for r in range(ar - 1, ar + 2):
                    for c in range(ac + 1, ac + 6):
                        if 0 <= r < env.height and 0 <= c < env.width and env.waste[r, c]:
                            hits += 1
            elif o == 2: # South
                for r in range(ar + 1, ar + 6):
                    for c in range(ac - 1, ac + 2):
                        if 0 <= r < env.height and 0 <= c < env.width and env.waste[r, c]:
                            hits += 1
            elif o == 3: # West
                for r in range(ar - 1, ar + 2):
                    for c in range(ac - 5, ac):
                        if 0 <= r < env.height and 0 <= c < env.width and env.waste[r, c]:
                            hits += 1
            return hits

        # 1. Check which orientation would clear the most waste right now
        max_hits = get_hits(orient)
        best_act = 8  # CLEAN (Default to firing if current orientation is best)

        # Check Left, Right, and Back
        for rot_dir, act in [((orient - 1) % 4, 4), ((orient + 1) % 4, 5), ((orient + 2) % 4, 4)]:
            hits = get_hits(rot_dir)
            if hits > max_hits:
                max_hits = hits
                best_act = act

        # If any orientation clears waste, either rotate towards it or fire CLEAN
        if max_hits > 0:
            return best_act

        # 2. If no waste in immediate range, find path to nearest waste
        waste_cells = set()
        for r in range(int(env.height)):
            for c in range(int(env.width)):
                if env.waste[r, c]:
                    waste_cells.add((r, c))

        if len(waste_cells) > 0:
            res = bfs_to_target_set(env, agent_id, waste_cells)
            if res is not None:
                dr, dc = res
                return direction_to_action(dr, dc, orient)

        # 3. If river is pristine but we aren't in it, return to the river
        if (ar, ac) not in env.river_cells_set:
            res = bfs_to_target_set(env, agent_id, env.river_cells_set)
            if res is not None:
                dr, dc = res
                return direction_to_action(dr, dc, orient)

        # 4. Stand by in the river
        return 7

    else:
        # Harvester Logic
        res = bfs_nearest_apple(env, agent_id)
        if res is not None:
            dr, dc = res
            return direction_to_action(dr, dc, orient)

        # If no apples exist, spread out along the inner edge of the orchard
